mapper.select:
SELECT id, enterprise_user_id AS enterpriseUserId, enterprise_name AS enterpriseName, title, description, required_major AS requiredMajor, min_experience AS minExperience, max_experience AS maxExperience, min_salary AS minSalary, max_salary AS maxSalary, location, status, created_at AS createdAt, updated_at AS updatedAt FROM job_postings WHERE status = 'OPEN'
AND (
(title LIKE CONCAT('%', #{kw}, '%') OR description LIKE CONCAT('%', #{kw}, '%'))
)
AND required_major LIKE CONCAT('%', #{major}, '%')
AND max_salary >= #{minSalary}
AND min_experience <= #{workExperience}
AND location LIKE CONCAT('%', #{location}, '%')
